// n8n Code node (Run Once for All Items) - "02 Validate Input"
// Checks the shape of the payload sent by Bubble and normalises numbers. It never trusts the sender:
// anything missing/invalid becomes a validation failure that is returned to Bubble as status "Failed".
const item = $input.first().json;
const b = (item && item.body) || {};
const errors = [];

const isStr = (v) => typeof v === 'string' && v.trim().length > 0;
// tolerant of how Bubble prints numbers inside text (e.g. "3,570" or "₹3570"), strict about everything else
const toNum = (v) => {
  if (v === null || v === undefined) return NaN;
  const s = String(v).replace(/[,\s₹]/g, '');
  return s === '' ? NaN : Number(s);
};
const optStr = (v) => (v === null || v === undefined ? '' : String(v));

// Bubble's API Connector substitutes a saved sample value when a field is empty. The sample values are the
// marker "__MISSING__", so an empty field can never turn into believable data - it fails here instead.
if (JSON.stringify(b).indexOf('__MISSING__') >= 0) errors.push('a required field was empty in the request from Bubble');
if (!isStr(b.request_id)) errors.push('request_id is missing');
if (!b.author || !isStr(b.author.author_id) || !isStr(b.author.name)) errors.push('author.author_id and author.name are required');
if (!/^\d{4}-\d{2}-\d{2}/.test(String(b.reference_date || ''))) errors.push('reference_date must be YYYY-MM-DD');

let books = b.books;
if (typeof books === 'string') {
  try { books = JSON.parse(books); } catch (e) { errors.push('books is not valid JSON'); books = null; }
}
if (!Array.isArray(books) || books.length < 1) errors.push('books must be a non-empty array');

const STATUSES = ['Paid up', 'In cycle', 'Overdue', 'Not applicable'];
const clean = [];
(Array.isArray(books) ? books : []).forEach((bk, i) => {
  const tag = 'books[' + i + ']';
  if (!bk || !isStr(bk.book_id) || !isStr(bk.title)) { errors.push(tag + ' needs book_id and title'); return; }
  if (!isStr(bk.status)) errors.push(tag + '.status is missing');
  const nums = {};
  ['copies_sold', 'total_earned', 'paid', 'pending'].forEach((k) => {
    const n = toNum(bk[k]);
    if (Number.isNaN(n) || n < 0) errors.push(tag + '.' + k + ' must be a number >= 0');
    nums[k] = n;
  });
  if (!STATUSES.includes(bk.royalty_status)) errors.push(tag + '.royalty_status must be one of ' + STATUSES.join('/'));
  clean.push({
    book_id: String(bk.book_id), title: String(bk.title), status: optStr(bk.status),
    publication_date: optStr(bk.publication_date).slice(0, 10), last_payout_date: optStr(bk.last_payout_date).slice(0, 10),
    mrp: bk.mrp === null || bk.mrp === undefined || bk.mrp === '' ? null : toNum(bk.mrp),
    royalty_per_copy: bk.royalty_per_copy === null || bk.royalty_per_copy === undefined || bk.royalty_per_copy === '' ? null : toNum(bk.royalty_per_copy),
    copies_sold: nums.copies_sold, total_earned: nums.total_earned, paid: nums.paid, pending: nums.pending,
    royalty_status: bk.royalty_status,
  });
});

const t = b.totals || {};
const totals = { earned: toNum(t.earned), paid: toNum(t.paid), pending: toNum(t.pending) };
['earned', 'paid', 'pending'].forEach((k) => { if (Number.isNaN(totals[k])) errors.push('totals.' + k + ' must be a number'); });

return [{
  json: {
    ok: errors.length === 0,
    errors,
    fail_stage: 'validation',
    fail_message: errors.join('; '),
    payload: {
      request_id: optStr(b.request_id),
      trigger_type: optStr(b.trigger_type),
      batch_id: optStr(b.batch_id) === 'null' ? '' : optStr(b.batch_id),
      requested_by: optStr(b.requested_by),
      requested_at: optStr(b.requested_at),
      reference_date: optStr(b.reference_date).slice(0, 10),
      demo_mode: b.demo_mode === true || b.demo_mode === 'true',
      author: {
        author_id: b.author ? optStr(b.author.author_id) : '', name: b.author ? optStr(b.author.name) : '',
        email: b.author ? optStr(b.author.email) : '', city: b.author ? optStr(b.author.city) : '',
      },
      books: clean,
      totals,
    },
  },
}];

// n8n Code node (Run Once for All Items) - "04 Acquire author lock"
// BEST-EFFORT de-duplication only. Workflow static data is not atomic, is not safely shared between
// parallel executions, persists only for production runs and is lost on restart. The enforced guard is
// Bubble's claim-then-arbitrate step; this is a second, courtesy layer
const d = $input.first().json;
const sd = $getWorkflowStaticData('global');
sd.locks = sd.locks || {};
const now = Date.now();
const TTL_MS = 5 * 60 * 1000;

Object.keys(sd.locks).forEach((k) => { if (now - sd.locks[k].ts > TTL_MS) delete sd.locks[k]; });

const key = d.payload.author.author_id;
const existing = sd.locks[key];
let duplicate = false;
if (existing && existing.request_id !== d.payload.request_id) {
  duplicate = true;
} else {
  sd.locks[key] = { request_id: d.payload.request_id, ts: now };
}

return [{
  json: Object.assign({}, d, {
    duplicate,
    fail_stage: duplicate ? 'duplicate' : d.fail_stage,
    fail_message: duplicate ? 'Another summary for this author is already being generated (n8n lock held by request ' + existing.request_id + ')' : '',
  }),
}];

// n8n Code node (Run Once for All Items) - "06 Integrity & facts"
// 1) Re-checks the arithmetic Bubble sent.  2) Computes EVERY number/date the email may contain, in code.
// 3) Chooses the payout-timing mode and builds the OpenAI request.  The model only writes wording.
const d = $input.first().json;
const p = d.payload;

// ---- constants (policy values come from the original Assignment 1 Knowledge Base; see IMPLEMENTATION_PLAN.md 10.8)
const MODEL = 'gpt-4o-mini';
const WINDOW_DAYS = 45;            // "paid within 45 days of the quarter ending"
const MIN_PAYOUT = 1000;           // "Minimum payout threshold: Rs 1,000 ... roll over to the next quarter"
const ESCALATION_COMMITMENT_ENABLED = false; // the KB's "within 48 hours" wording is only for real escalations
const MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];

// ---- formatting helpers (Indian digit grouping, no Intl dependency)
function grp(n) {
  const s = String(Math.round(Math.abs(n)));
  let last3 = s.slice(-3);
  let rest = s.slice(0, -3);
  if (rest) last3 = ',' + last3;
  rest = rest.replace(/\B(?=(\d{2})+(?!\d))/g, ',');
  return (n < 0 ? '-' : '') + rest + last3;
}
const inr = (n) => '₹' + grp(n);
function ymd(s) { const m = /^(\d{4})-(\d{2})-(\d{2})/.exec(s || ''); return m ? { y: +m[1], m: +m[2], d: +m[3] } : null; }
function fmtIso(s) { const q = ymd(s); return q ? q.d + ' ' + MONTHS[q.m - 1] + ' ' + q.y : null; }
function fmtObj(dt) { return dt.getUTCDate() + ' ' + MONTHS[dt.getUTCMonth()] + ' ' + dt.getUTCFullYear(); }

// ---- 1. integrity: do not trust the sender
const problems = [];
let sumE = 0, sumP = 0, sumN = 0;
p.books.forEach((b) => {
  const published = b.status.indexOf('Published') === 0;
  sumE += b.total_earned; sumP += b.paid; sumN += b.pending;
  if (b.paid + b.pending !== b.total_earned) problems.push(b.book_id + ': paid + pending != total earned');
  if (b.mrp !== null && b.royalty_per_copy !== null && b.copies_sold * b.royalty_per_copy !== b.total_earned) problems.push(b.book_id + ': copies x royalty per copy != total earned');
  if (!published && (b.pending !== 0 || b.total_earned !== 0)) problems.push(b.book_id + ': unpublished book carries royalty figures');
  if (published && b.pending === 0 && b.royalty_status !== 'Paid up') problems.push(b.book_id + ': status inconsistent with zero pending');
  if (published && b.pending > 0 && b.royalty_status !== 'In cycle' && b.royalty_status !== 'Overdue') problems.push(b.book_id + ': status inconsistent with pending amount');
  if (!published && b.royalty_status !== 'Not applicable') problems.push(b.book_id + ': unpublished book must be Not applicable');
});
if (sumE !== p.totals.earned || sumP !== p.totals.paid || sumN !== p.totals.pending) problems.push('book totals (' + sumE + '/' + sumP + '/' + sumN + ') differ from the totals Bubble sent');
if (problems.length) {
  return [{ json: { ok: false, fail_stage: 'data', fail_message: 'Data integrity check failed: ' + problems.join('; '), payload: p } }];
}

// ---- 2. deterministic facts
const ref = ymd(p.reference_date);
const refUtc = Date.UTC(ref.y, ref.m - 1, ref.d);
const qEnds = [];
[ref.y - 1, ref.y, ref.y + 1].forEach((y) => { [[2, 31], [5, 30], [8, 30], [11, 31]].forEach((q) => qEnds.push(Date.UTC(y, q[0], q[1]))); });
let last = null, next = null;
qEnds.forEach((t) => { if (t < refUtc) last = t; if (next === null && t >= refUtc) next = t; });
const DAY = 86400000;
const lastDeadline = last + WINDOW_DAYS * DAY;
const dueBy = refUtc <= lastDeadline ? lastDeadline : next + WINDOW_DAYS * DAY;
const dueByText = fmtObj(new Date(dueBy));

const published = p.books.filter((b) => b.status.indexOf('Published') === 0);
const production = p.books.filter((b) => b.status.indexOf('Published') !== 0);
const overdueBooks = published.filter((b) => b.royalty_status === 'Overdue');
const inCycleBooks = published.filter((b) => b.royalty_status === 'In cycle');
const pendingTotal = p.totals.pending;

let mode = 'ALL_PAID';
if (published.length === 0) mode = 'NO_ROYALTIES_YET';
else if (overdueBooks.length > 0) mode = 'OVERDUE';
else if (inCycleBooks.length > 0) mode = 'IN_CYCLE';

const flags = [];
if (published.some((b) => b.pending > 0 && b.paid === 0 && b.copies_sold > 0)) flags.push('NEVER_PAID');
if (pendingTotal > 0 && pendingTotal < MIN_PAYOUT) flags.push('BELOW_THRESHOLD');
// KB rule wins over the app's 90-day colour rule: an amount under the minimum payout is not "late", it rolls over.
if (flags.indexOf('BELOW_THRESHOLD') >= 0) mode = 'BELOW_THRESHOLD';
if (production.length > 0) flags.push('HAS_PRODUCTION');

const dateAllowed = mode === 'IN_CYCLE' || (mode === 'OVERDUE' && inCycleBooks.length > 0);
const facts = {
  author_first_name: p.author.name.split(' ')[0],
  author_full_name: p.author.name,
  generated_on: fmtIso(p.reference_date),
  payout_mode: mode,
  scenario_flags: flags,
  published_books: published.map((b) => ({
    title: b.title,
    copies_sold: grp(b.copies_sold),
    total_earned: inr(b.total_earned),
    paid: inr(b.paid),
    pending: inr(b.pending),
    last_payout: b.last_payout_date ? fmtIso(b.last_payout_date) : 'no payout recorded yet',
    royalty_status: (mode === 'BELOW_THRESHOLD' && b.pending > 0) ? 'Below minimum payout (rolls over)' : b.royalty_status,
  })),
  production_books: production.map((b) => ({ title: b.title, stage: b.status.replace(/^In Production\s*-\s*/i, '') })),
  totals: { earned: inr(p.totals.earned), paid: inr(p.totals.paid), pending: inr(p.totals.pending) },
  payout_policy: {
    cycle: 'Royalties are calculated quarterly and paid within ' + WINDOW_DAYS + ' days of the quarter ending',
    minimum_payout: inr(MIN_PAYOUT),
    below_minimum_rule: 'If accumulated royalties are below the minimum payout, they roll over to the next quarter',
    date_statement_allowed: dateAllowed,
    standard_due_by: dateAllowed ? dueByText : null,
    titles_with_standard_due_date: dateAllowed ? inCycleBooks.map((b) => b.title) : [],
    below_threshold: flags.indexOf('BELOW_THRESHOLD') >= 0,
  },
  overdue_titles: overdueBooks.map((b) => b.title),
};

// numbers/dates the email may legitimately contain = those present in the facts + the two policy numbers
const factsText = JSON.stringify(facts);
const allowedNumbers = Array.from(new Set((factsText.match(/\d[\d,]*/g) || []).map((s) => s.replace(/,/g, '')).concat([String(WINDOW_DAYS), String(MIN_PAYOUT)])));
const allowedDates = [];
if (facts.generated_on) allowedDates.push(facts.generated_on);
facts.published_books.forEach((b) => { if (b.last_payout.match(/\d{4}$/)) allowedDates.push(b.last_payout); });
if (dateAllowed) allowedDates.push(dueByText);

// ---- 3. prompt
const KB = [
  'ROYALTY POLICY (BookLeaf Knowledge Base)',
  '- 80/20 split: 80% of the net profit per book goes to the author, 20% to BookLeaf.',
  '- Royalties are calculated quarterly and paid within 45 days of the quarter ending.',
  '- Minimum payout threshold: ₹1,000. If accumulated royalties are below this, they roll over to the next quarter.',
  '- Payouts are made via bank transfer to the account linked in the author\'s dashboard.',
  '',
  'TONE GUIDELINES (how BookLeaf talks to authors)',
  '- Always empathetic and professional. Authors are our partners, not customers to be managed.',
  '- Acknowledge the author\'s concern before jumping to solutions.',
  '- Be specific: include actual numbers, dates and statuses wherever possible rather than vague reassurances.',
  '- If something is BookLeaf\'s fault (delayed royalties), own it directly. No corporate deflection.',
  '- Always end with a clear next step for the author and/or the BookLeaf team.',
].join('\n');

const scenario = [];
if (mode === 'ALL_PAID') scenario.push('All royalties are paid up. Thank the author warmly and acknowledge their success. Do NOT mention outstanding amounts, next payouts or payout dates.');
if (mode === 'NO_ROYALTIES_YET') scenario.push('There are no published books yet, so no royalties exist. Give a brief, warm status update on the book(s) in production only.');
if (mode === 'IN_CYCLE') scenario.push('There are pending royalties and none are overdue. State the pending amounts, explain the quarterly cycle and the 45-day window, and say that under BookLeaf\'s standard cycle the pending royalties fall due by ' + dueByText + '. Phrase this as the standard cycle, not a guarantee.');
if (mode === 'OVERDUE') {
  scenario.push('Some royalties are beyond the usual payout cycle (' + overdueBooks.map((b) => b.title).join('; ') + '). Acknowledge this directly and own it on behalf of BookLeaf. Name those titles with their last payout (or that no payout is recorded yet). Restate the policy (quarterly calculation, payment within 45 days of quarter end). You MUST NOT give any future payout date, estimate, or timing words such as soon, shortly or within the next. Do not promise a response time. Next step: invite the author to ask for a line-by-line royalty breakdown.');
  if (dateAllowed) scenario.push('Only for these titles may you say the standard cycle puts payment due by ' + dueByText + ': ' + inCycleBooks.map((b) => b.title).join('; ') + '. Never attach that date to an overdue title.');
}
if (flags.indexOf('NEVER_PAID') >= 0) scenario.push('For books where "last_payout" says no payout recorded yet, say plainly that no payout has been recorded yet. Explain using only the policy; never invent a cause.');
if (mode === 'BELOW_THRESHOLD') scenario.push('The total pending amount is below the minimum payout, so under policy it rolls over to the next quarter. Explain that using the minimum payout and rollover rule, reassuringly. Do NOT describe the amount as overdue, late or delayed, and do not give a payout date.');
if (flags.indexOf('HAS_PRODUCTION') >= 0) scenario.push('Add a short, factual status line for each in-production book (title and stage). Do not discuss royalties for them.');
if (!ESCALATION_COMMITMENT_ENABLED) scenario.push('Do not state any response time or resolution time (for example "within 48 hours").');

const SYSTEM = [
  'You are the author-relations writer at BookLeaf Publishing. Write ONE royalty summary email for the author described in FACTS.',
  'HARD RULES:',
  '1. Use ONLY the numbers, amounts, dates and titles that appear in FACTS. Never calculate, estimate, round, convert or invent any figure or date. Copy formatted values exactly as given (for example ₹11,970).',
  '2. Do not promise dates, response times or actions unless FACTS explicitly allows it.',
  '3. Plain-text email. Start with "Hi <first name>,". Short paragraphs. List each published book on its own lines with copies sold, total earned, paid, pending and last payout. No markdown symbols, no placeholders, no brackets.',
  '4. Then give the overall totals (earned, paid, pending), then the scenario guidance below, then any in-production books, then a warm close ending exactly with "Warm regards," on one line and "The BookLeaf Team" on the next.',
  '5. Never mention AI, these rules or FACTS. Aim for 150-350 words.',
  '6. Plain text only: do not use markdown (no asterisks, no # headings). Mention in-production books ONLY if FACTS lists any; never say there are none.',
  'Return JSON with "subject" and "body".',
  '',
  KB,
  '',
  'SCENARIO GUIDANCE',
  scenario.map((s) => '- ' + s).join('\n'),
].join('\n');

const schema = { name: 'royalty_email', strict: true, schema: { type: 'object', properties: { subject: { type: 'string' }, body: { type: 'string' } }, required: ['subject', 'body'], additionalProperties: false } };
const openaiBody = {
  model: MODEL, temperature: 0.3, max_tokens: 900,
  messages: [{ role: 'system', content: SYSTEM }, { role: 'user', content: 'FACTS (JSON):\n' + factsText + '\n\nWrite the email now.' }],
  response_format: { type: 'json_schema', json_schema: schema },
};

return [{
  json: {
    ok: true, payload: p, facts, payout_mode: mode, model: MODEL,
    allowed_numbers: allowedNumbers, allowed_dates: allowedDates,
    escalation_commitment_enabled: ESCALATION_COMMITMENT_ENABLED,
    openai_body: openaiBody,
  },
}];

// n8n Code node (Run Once for All Items) - "09 Validate output" (attempt 1) / "12 Validate output (retry)" (attempt 2)
// Never trust the model: every number, date and required element is checked against the deterministic facts.
const ATTEMPT = 1; // the build script sets this to 2 for the retry node
const ctx = $('06 Integrity & facts').first().json;
const facts = ctx.facts;
const resp = $input.first().json;
const violations = [];
let subject = '';
let body = '';

try {
  const content = resp.choices[0].message.content;
  const j = JSON.parse(content);
  subject = typeof j.subject === 'string' ? j.subject.trim() : '';
  body = typeof j.body === 'string' ? j.body.trim() : '';
} catch (e) {
  violations.push('The model output was not valid JSON with "subject" and "body".');
}
if (!subject) violations.push('Subject is empty.');
if (!body) violations.push('Body is empty.');

if (body) {
  const mode = ctx.payout_mode;
  const flags = facts.scenario_flags;
  const allowedNums = ctx.allowed_numbers;
  const allowedDates = ctx.allowed_dates;
  const MONTHS = 'January|February|March|April|May|June|July|August|September|October|November|December';

  // 1. number whitelist
  const nums = body.match(/\d[\d,]*/g) || [];
  nums.forEach((t) => {
    const n = t.replace(/,+$/, '').replace(/,/g, '');
    if (allowedNums.indexOf(n) < 0) violations.push('Unknown number "' + t + '" (not in FACTS).');
  });

  // 2. date whitelist
  const dateRe = new RegExp('\\b\\d{1,2} (?:' + MONTHS + ') \\d{4}\\b', 'g');
  (body.match(dateRe) || []).forEach((dt) => {
    if (allowedDates.indexOf(dt) < 0) violations.push('Date "' + dt + '" is not allowed here.');
  });

  // 3. required content
  if (body.slice(0, 160).indexOf(facts.author_first_name) < 0) violations.push('The greeting must use the author\'s first name.');
  facts.published_books.forEach((b) => { if (body.indexOf(b.title) < 0) violations.push('Missing published book "' + b.title + '".'); });
  facts.production_books.forEach((b) => { if (body.indexOf(b.title) < 0) violations.push('Missing in-production book "' + b.title + '".'); });
  ['earned', 'paid', 'pending'].forEach((k) => { if (body.indexOf(facts.totals[k]) < 0) violations.push('Missing total ' + k + ' (' + facts.totals[k] + ').'); });
  if (!/Warm regards,\s*\n?\s*The BookLeaf Team\s*$/.test(body)) violations.push('The email must end with "Warm regards," then "The BookLeaf Team".');

  // 4. mode-specific rules
  if (mode === 'ALL_PAID') {
    if (/outstanding|next payout|due by|will be paid|upcoming payout/i.test(body)) violations.push('All-paid email must not mention outstanding amounts or upcoming payouts.');
  }
  if (mode === 'OVERDUE') {
    if (/\b(soon|shortly|within the next|by the end of)\b/i.test(body)) violations.push('Overdue email must not use timing promises (soon/shortly/within the next/by the end of).');
    if (/will be (paid|credited|processed|released|transferred|disbursed)/i.test(body)) violations.push('Overdue email must not promise a future payment.');
  }
  if (mode === 'IN_CYCLE') {
    if (facts.payout_policy.standard_due_by && body.indexOf(facts.payout_policy.standard_due_by) < 0) violations.push('Must state the standard due date ' + facts.payout_policy.standard_due_by + '.');
  }
  if (mode === 'BELOW_THRESHOLD' && /\b(overdue|late|delay\w*)\b/i.test(body)) violations.push('Below-minimum email must not call the amount overdue, late or delayed.');
  if (/\*\*|^#{1,6}\s/m.test(body)) violations.push('Plain text only: markdown symbols are not allowed.');
  if (facts.production_books.length === 0 && /production/i.test(body)) violations.push('Mentions production although no book is in production.');
  if (mode === 'OVERDUE' && !facts.payout_policy.date_statement_allowed && ctx.allowed_dates.length && /\bdue by\b/i.test(body)) violations.push('Overdue email must not state a due-by date.');
  if (flags.indexOf('BELOW_THRESHOLD') >= 0) {
    if (body.indexOf(facts.payout_policy.minimum_payout) < 0 || !/next quarter/i.test(body)) violations.push('Must explain the minimum payout and rollover to the next quarter.');
  }

  // 5. forbidden patterns
  if (/\[|\]|\{\{|\}\}|TODO|guarantee|as an AI|\bAI\b|FACTS/i.test(body + ' ' + subject)) violations.push('Contains a placeholder, "guarantee", or a reference to AI/FACTS.');
  if (!ctx.escalation_commitment_enabled) {
    const stripped = body.replace(/45[- ]days?/gi, '');
    if (/\b(within|in)\s+(a|an|one|two|three|\d+)\s+(hours?|days?|business days?)\b/i.test(stripped)) violations.push('Contains a response-time commitment, which is not enabled.');
  }

  // 6. length
  const words = body.split(/\s+/).filter(Boolean).length;
  if (words < 80 || words > 450) violations.push('Length ' + words + ' words is outside 80-450.');
}

const ok = violations.length === 0;
const out = { ok, violations, attempt: ATTEMPT, email_subject: subject, email_body: body, fail_stage: ok ? '' : 'output_validation', fail_message: ok ? '' : 'AI output failed validation after ' + ATTEMPT + ' attempt(s): ' + violations.join(' | ') };

if (!ok && ATTEMPT === 1) {
  const retryBody = JSON.parse(JSON.stringify(ctx.openai_body));
  retryBody.messages.push({ role: 'assistant', content: JSON.stringify({ subject, body }) });
  retryBody.messages.push({ role: 'user', content: 'Your draft broke these rules:\n- ' + violations.join('\n- ') + '\nWrite the email again, fixing every point. Use only numbers and dates from FACTS.' });
  out.openai_body_retry = retryBody;
}
return [{ json: out }];

// n8n Code node (Run Once for All Items) - "90 Build success response"
// Output is returned to Bubble as the webhook's HTTP response (Bubble's Free plan cannot receive a separate callback).
const v = $input.first().json; // result of the output validator that passed
const ctx = $('06 Integrity & facts').first().json;
const p = ctx.payload;
return [{
  json: {
    http_code: 200,
    response: {
      request_id: p.request_id,
      status: 'Success',
      completed_at: new Date().toISOString(),
      email_subject: v.email_subject,
      email_body: v.email_body,
      recipient_email: p.author.email,
      ai_model: ctx.model,
      failure_stage: '',
      error_message: '',
      n8n_execution_id: String($execution.id),
      pending_snapshot: p.totals.pending,
      payout_mode: ctx.payout_mode,
      attempts: v.attempt,
      demo_mode: p.demo_mode,
      reference_date_used: p.reference_date,
    },
  },
}];

// n8n Code node (Run Once for All Items) - "09 Validate output" (attempt 1) / "12 Validate output (retry)" (attempt 2)
// Never trust the model: every number, date and required element is checked against the deterministic facts.
const ATTEMPT = 2; // the build script sets this to 2 for the retry node
const ctx = $('06 Integrity & facts').first().json;
const facts = ctx.facts;
const resp = $input.first().json;
const violations = [];
let subject = '';
let body = '';

try {
  const content = resp.choices[0].message.content;
  const j = JSON.parse(content);
  subject = typeof j.subject === 'string' ? j.subject.trim() : '';
  body = typeof j.body === 'string' ? j.body.trim() : '';
} catch (e) {
  violations.push('The model output was not valid JSON with "subject" and "body".');
}
if (!subject) violations.push('Subject is empty.');
if (!body) violations.push('Body is empty.');

if (body) {
  const mode = ctx.payout_mode;
  const flags = facts.scenario_flags;
  const allowedNums = ctx.allowed_numbers;
  const allowedDates = ctx.allowed_dates;
  const MONTHS = 'January|February|March|April|May|June|July|August|September|October|November|December';

  // 1. number whitelist
  const nums = body.match(/\d[\d,]*/g) || [];
  nums.forEach((t) => {
    const n = t.replace(/,+$/, '').replace(/,/g, '');
    if (allowedNums.indexOf(n) < 0) violations.push('Unknown number "' + t + '" (not in FACTS).');
  });

  // 2. date whitelist
  const dateRe = new RegExp('\\b\\d{1,2} (?:' + MONTHS + ') \\d{4}\\b', 'g');
  (body.match(dateRe) || []).forEach((dt) => {
    if (allowedDates.indexOf(dt) < 0) violations.push('Date "' + dt + '" is not allowed here.');
  });

  // 3. required content
  if (body.slice(0, 160).indexOf(facts.author_first_name) < 0) violations.push('The greeting must use the author\'s first name.');
  facts.published_books.forEach((b) => { if (body.indexOf(b.title) < 0) violations.push('Missing published book "' + b.title + '".'); });
  facts.production_books.forEach((b) => { if (body.indexOf(b.title) < 0) violations.push('Missing in-production book "' + b.title + '".'); });
  ['earned', 'paid', 'pending'].forEach((k) => { if (body.indexOf(facts.totals[k]) < 0) violations.push('Missing total ' + k + ' (' + facts.totals[k] + ').'); });
  if (!/Warm regards,\s*\n?\s*The BookLeaf Team\s*$/.test(body)) violations.push('The email must end with "Warm regards," then "The BookLeaf Team".');

  // 4. mode-specific rules
  if (mode === 'ALL_PAID') {
    if (/outstanding|next payout|due by|will be paid|upcoming payout/i.test(body)) violations.push('All-paid email must not mention outstanding amounts or upcoming payouts.');
  }
  if (mode === 'OVERDUE') {
    if (/\b(soon|shortly|within the next|by the end of)\b/i.test(body)) violations.push('Overdue email must not use timing promises (soon/shortly/within the next/by the end of).');
    if (/will be (paid|credited|processed|released|transferred|disbursed)/i.test(body)) violations.push('Overdue email must not promise a future payment.');
  }
  if (mode === 'IN_CYCLE') {
    if (facts.payout_policy.standard_due_by && body.indexOf(facts.payout_policy.standard_due_by) < 0) violations.push('Must state the standard due date ' + facts.payout_policy.standard_due_by + '.');
  }
  if (mode === 'BELOW_THRESHOLD' && /\b(overdue|late|delay\w*)\b/i.test(body)) violations.push('Below-minimum email must not call the amount overdue, late or delayed.');
  if (/\*\*|^#{1,6}\s/m.test(body)) violations.push('Plain text only: markdown symbols are not allowed.');
  if (facts.production_books.length === 0 && /production/i.test(body)) violations.push('Mentions production although no book is in production.');
  if (mode === 'OVERDUE' && !facts.payout_policy.date_statement_allowed && ctx.allowed_dates.length && /\bdue by\b/i.test(body)) violations.push('Overdue email must not state a due-by date.');
  if (flags.indexOf('BELOW_THRESHOLD') >= 0) {
    if (body.indexOf(facts.payout_policy.minimum_payout) < 0 || !/next quarter/i.test(body)) violations.push('Must explain the minimum payout and rollover to the next quarter.');
  }

  // 5. forbidden patterns
  if (/\[|\]|\{\{|\}\}|TODO|guarantee|as an AI|\bAI\b|FACTS/i.test(body + ' ' + subject)) violations.push('Contains a placeholder, "guarantee", or a reference to AI/FACTS.');
  if (!ctx.escalation_commitment_enabled) {
    const stripped = body.replace(/45[- ]days?/gi, '');
    if (/\b(within|in)\s+(a|an|one|two|three|\d+)\s+(hours?|days?|business days?)\b/i.test(stripped)) violations.push('Contains a response-time commitment, which is not enabled.');
  }

  // 6. length
  const words = body.split(/\s+/).filter(Boolean).length;
  if (words < 80 || words > 450) violations.push('Length ' + words + ' words is outside 80-450.');
}

const ok = violations.length === 0;
const out = { ok, violations, attempt: ATTEMPT, email_subject: subject, email_body: body, fail_stage: ok ? '' : 'output_validation', fail_message: ok ? '' : 'AI output failed validation after ' + ATTEMPT + ' attempt(s): ' + violations.join(' | ') };

if (!ok && ATTEMPT === 1) {
  const retryBody = JSON.parse(JSON.stringify(ctx.openai_body));
  retryBody.messages.push({ role: 'assistant', content: JSON.stringify({ subject, body }) });
  retryBody.messages.push({ role: 'user', content: 'Your draft broke these rules:\n- ' + violations.join('\n- ') + '\nWrite the email again, fixing every point. Use only numbers and dates from FACTS.' });
  out.openai_body_retry = retryBody;
}
return [{ json: out }];

// n8n Code node (Run Once for All Items) - "98 Build failed response"
// Every failure branch (validation, duplicate, data, ai, output_validation) ends here, so Bubble always gets a
// structured Failed/Skipped result with a stage and a human-readable reason - never silence.
const j = $input.first().json;
let p = {};
try { p = $('02 Validate Input').first().json.payload || {}; } catch (e) { p = {}; }

let stage = j.fail_stage;
let message = j.fail_message;
if (j.error) { // an error output of an HTTP node (the OpenAI call)
  const e = j.error;
  stage = 'ai';
  message = 'AI request failed: ' + (e.message || 'unknown error') + (e.httpCode ? ' (HTTP ' + e.httpCode + ')' : '') + (e.description ? ' - ' + String(e.description).slice(0, 200) : '');
}
stage = stage || 'unknown';
message = message || 'Unknown failure';

return [{
  json: {
    http_code: 200,
    response: {
      request_id: p.request_id || '',
      status: stage === 'duplicate' ? 'Skipped' : 'Failed',
      completed_at: new Date().toISOString(),
      email_subject: '',
      email_body: '',
      recipient_email: p.author ? p.author.email : '',
      ai_model: '',
      failure_stage: stage,
      error_message: String(message).slice(0, 900),
      n8n_execution_id: String($execution.id),
      pending_snapshot: p.totals ? p.totals.pending : 0,
      payout_mode: '',
      attempts: 0,
      demo_mode: !!p.demo_mode,
      reference_date_used: p.reference_date || '',
    },
  },
}];

// n8n Code node (Run Once for All Items) - "99 Release author lock" (runs after the response has been sent)
// Releases only the lock this request owns, so a duplicate request can never release the original's lock.
let p = null;
try { p = $('02 Validate Input').first().json.payload; } catch (e) { p = null; }
if (p && p.author && p.author.author_id) {
  const sd = $getWorkflowStaticData('global');
  if (sd.locks && sd.locks[p.author.author_id] && sd.locks[p.author.author_id].request_id === p.request_id) {
    delete sd.locks[p.author.author_id];
  }
}
return [{ json: { released: true } }];
